// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address ref, uint256 drugsAmount, uint256 blockTime) public {
        // Bound inputs to reasonable ranges
        vm.assume(ref != address(c)); // avoid self-referral complexity

        // Set up seed market
        uint256 seedDrugs = 1000000;
        c.seedMarket{value: 10 ether}(seedDrugs);

        // Give caller some initial drugs via buy
        uint256 buyValue = 1 ether + bound(drugsAmount, 1 wei, 10 ether);
        vm.deal(address(this), buyValue);
        c.buyDrugs{value: buyValue}();

        // Warp time to have earnable drugs
        vm.warp(blockTime % 1000000 + 100000);

        // Record state before collectDrugs
        uint256 marketBefore = c.marketDrugs();
        uint256 drugsUsed = c.getMyDrugs();

        // Call collectDrugs
        c.collectDrugs(ref);

        // Assert: marketDrugs increases by exactly drugsUsed/10
        uint256 expectedIncrease = drugsUsed / 10;
        assertTrue(c.marketDrugs() == marketBefore + expectedIncrease, "marketDrugs should increase by drugsUsed/10 in collectDrugs");
    }
}

